vec2 d = (vec2(1.0)/uTexSize) * 8.0;
vec3 dx = ( GetBlur1(uv + vec2( 1.0 , 0.0 )*d) - GetBlur1(uv-vec2( 1.0 , 0.0 )*d).xy );
vec3 dy = ( GetBlur1(uv + vec2( 0.0 , 1.0 )*d) - GetBlur1(uv-vec2( 0.0 , 1.0 )*d).xy );
vec2 dither_uv = uv_orig*uTexSize.xy*texsize_noise_lq.zw * .3 + rand_frame.xy;
vec2 my_uv =  mix(uv_orig, uv, 1.0) ;
vec2 uv_x= my_uv + vec2(dx.x,dy.x)*(vec2(1.0)/uTexSize) * 4.0;
vec2 uv_y= my_uv + vec2(dx.y,dy.y)*(vec2(1.0)/uTexSize) * 4.0;
vec2 uv_z= my_uv + vec2(dx.z,dy.z)*(vec2(1.0)/uTexSize) * 4.0;
ret.x = GetPixel(uv_x).x - (GetPixel(uv_x).xy - GetBlur3(uv_x)).x  * 0.02;
ret.y = GetPixel(uv_y).y - (GetPixel(uv_y).xy - GetBlur3(uv_y)).y  * 0.02;
ret.z = GetPixel(uv_z).z - (GetPixel(uv_z).xy - GetBlur3(uv_z)).z  * 0.02;
ret += (texture(sampler_noise_lq, dither_uv).xyz-0.5) *0.1*(audioLow-audioHigh);
ret -= ret.yzx*0.1 - 0.04;
}

